class EmbedScalarCriticalPoints(Node):

    def __init__(self, parent_node_id : str, radius : float = 3.0, color_scheme : List[str] = ["#3b4cc0", "#aac7fd", "#f7b89c", "#b40426", "#000000"]):
        if correctness_checks_on():
            if len(color_scheme) != 5:
                raise Exception("color_scheme list should have five elements")

            for elt in color_scheme:
                if not is_hex_string(elt):
                    raise Exception(f"Element {elt} in color_scheme is not a hex string")

            del elt

        super().__init__(parent_node_id, types.ScalarCriticalPoints, types.ScalarCriticalPointsEmbedding, locals(), False, True)

        self.radius = radius
        self.color_scheme = color_scheme

    def compatible_to_visualize(self, other):
    def _evaluation_logic(self, parent_data, time_step):
        color_list = _generate_color_list(parent_data.tracking_ids)
        points_ids = PointAndCellIds(Input=parent_data.points)
        points_ids.GenerateCellIds = 0

        return types.TrackedVectorCriticalPointsEmbedding(points_ids, color_list, time_step, parent_data.tracking_ids, self.radius)

    def _evaluation_logic_partial_cache(self, parent_data, partial_cache, time_step):
        points_ids = PointAndCellIds(Input=parent_data.points)
        points_ids.GenerateCellIds = 0
        partial_cache.points = points_ids
        partial_cache.time_step = time_step
        return partial_cache

class EmbedTrackedVectorFieldCriticalPoints(Node):

    def __init__(self, parent_node_id : str, radius : float = 3.0):
        if correctness_checks_on():
            if radius <= 0:
                raise Exception(f"Radius must be positive, yet the radius specified was {radius}.")

        super().__init__(parent_node_id, types.TrackedVectorCriticalPoints, types.TrackedVectorCriticalPointsEmbedding, locals(), True, True)

        self.radius = radius

    @classmethod
    def chat_description(cls):
        return "queued embedding the tracked vector field critical points"

    @classmethod
    def description(cls):
        return 'Creates a geometric embedding of a set of tracked vector field critical points.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'A node of type tracked_vector_cp corresponding to the tracked '
                           'critical points to visualize.',
         'radius': 'The radius to use for the visualization.'}

    def compatible_to_visualize(self, other):
        if issubclass(other.node_type, types.VectorCriticalPointsEmbedding) and \
           self.parent_node.parent_node_id == other.parent_node_id:

            return False, "Cannot visualize a vector field's set of critical points both tracked and "\
                          "untracked at the same time. They will overlap."

        return True, ""

    def _evaluation_logic(self, parent_data, time_step):
        color_list = _generate_color_list(parent_data.tracking_ids)
        points_ids = PointAndCellIds(Input=parent_data.points)
        points_ids.GenerateCellIds = 0

        return types.TrackedVectorCriticalPointsEmbedding(points_ids, color_list, time_step, parent_data.tracking_ids, self.radius)

    def _evaluation_logic_partial_cache(self, parent_data, partial_cache, time_step):
        points_ids = PointAndCellIds(Input=parent_data.points)
        points_ids.GenerateCellIds = 0
        partial_cache.points = points_ids
        partial_cache.time_step = time_step
        return partial_cache

